import express, { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';
import crypto from 'crypto';

interface CacheConfig {
  redisUrl: string;
  ttl: number;
  prefix: string;
  securityHeaders: SecurityHeaderConfig;
}

interface SecurityHeaderConfig {
  contentSecurityPolicy: string;
  xFrameOptions: string;
  xContentTypeOptions: string;
  strictTransportSecurity: string;
}

class DistributedCacheClient {
  private redis: Redis;
  private config: CacheConfig;
  private headerPolicy: Map<string, string>;

  constructor(config: CacheConfig) {
    this.config = config;
    this.redis = new Redis(config.redisUrl);
    this.headerPolicy = new Map();
    this.initializeSecurityHeaders();
  }

  private initializeSecurityHeaders(): void {
    const headers = this.config.securityHeaders;
    this.headerPolicy.set('Content-Security-Policy', headers.contentSecurityPolicy);
    this.headerPolicy.set('X-Content-Type-Options', headers.xContentTypeOptions);
    this.headerPolicy.set('Strict-Transport-Security', headers.strictTransportSecurity);

    // Frame protection derived from environment-dependent ancestor origins
    const allowedAncestors = this.resolveFrameAncestors();
    if (allowedAncestors.length > 0) {
      this.headerPolicy.set('X-Frame-Options', this.deriveXFrameOptions(allowedAncestors));
      this.headerPolicy.set('Content-Security-Policy',
        this.augmentCSPWithFrameAncestors(headers.contentSecurityPolicy, allowedAncestors));
    } else {
      this.headerPolicy.set('X-Frame-Options', headers.xFrameOptions);
    }
  }

  private resolveFrameAncestors(): string[] {
    const envAncestors = process.env.ALLOWED_FRAME_ANCESTORS || '';
    if (!envAncestors.trim()) return [];

    return envAncestors.split(',').map(a => a.trim()).filter(a => a.length > 0);
  }

  private deriveXFrameOptions(ancestors: string[]): string {
    // If multiple ancestors specified, X-Frame-Options cannot represent them
    // so we rely on CSP frame-ancestors instead and set ALLOWALL as fallback
    // for legacy browsers that don't support CSP
    if (ancestors.length > 1) {
      return 'ALLOWALL';
    }
    return `ALLOW-FROM ${ancestors[0]}`;
  }

  private augmentCSPWithFrameAncestors(baseCSP: string, ancestors: string[]): string {
    const ancestorDirective = `frame-ancestors ${ancestors.join(' ')}`;
    if (baseCSP.includes('frame-ancestors')) {
      return baseCSP.replace(/frame-ancestors[^;]*/, ancestorDirective);
    }
    return `${baseCSP}; ${ancestorDirective}`;
  }

  public getSecurityMiddleware(): (req: Request, res: Response, next: NextFunction) => void {
    return (req: Request, res: Response, next: NextFunction) => {
      this.headerPolicy.forEach((value, key) => {
        res.setHeader(key, value);
      });
      next();
    };
  }

  public async get(key: string): Promise<string | null> {
    const prefixedKey = `${this.config.prefix}:${this.sanitizeKey(key)}`;
    return this.redis.get(prefixedKey);
  }

  public async set(key: string, value: string, ttl?: number): Promise<void> {
    const prefixedKey = `${this.config.prefix}:${this.sanitizeKey(key)}`;
    const effectiveTtl = ttl || this.config.ttl;
    await this.redis.setex(prefixedKey, effectiveTtl, value);
  }

  public async invalidate(key: string): Promise<void> {
    const prefixedKey = `${this.config.prefix}:${this.sanitizeKey(key)}`;
    await this.redis.del(prefixedKey);
  }

  private sanitizeKey(key: string): string {
    return key.replace(/[^a-zA-Z0-9_:-]/g, '_');
  }

  public async getCachedResponse(req: Request, res: Response, next: NextFunction): Promise<void> {
    const cacheKey = this.computeCacheKey(req);
    const cached = await this.get(cacheKey);
    if (cached) {
      const parsed = JSON.parse(cached);
      res.status(parsed.status).json(parsed.body);
      return;
    }
    next();
  }

  private computeCacheKey(req: Request): string {
    const hash = crypto.createHash('sha256');
    hash.update(`${req.method}:${req.originalUrl}`);
    return hash.digest('hex');
  }
}

// Application bootstrap
function loadConfig(): CacheConfig {
  const env = process.env.NODE_ENV || 'production';
  const baseConfig: CacheConfig = {
    redisUrl: process.env.REDIS_URL || 'redis://localhost:6379',
    ttl: parseInt(process.env.CACHE_TTL || '300', 10),
    prefix: process.env.CACHE_PREFIX || 'dcc',
    securityHeaders: {
      contentSecurityPolicy: "default-src 'self'; frame-ancestors 'none'",
      xFrameOptions: 'DENY',
      xContentTypeOptions: 'nosniff',
      strictTransportSecurity: 'max-age=31536000; includeSubDomains'
    }
  };

  // In staging/development, allow embedding for testing dashboards
  if (env !== 'production') {
    baseConfig.securityHeaders.xFrameOptions = 'SAMEORIGIN';
    baseConfig.securityHeaders.contentSecurityPolicy = "default-src 'self'; frame-ancestors 'self'";
  }

  return baseConfig;
}

const config = loadConfig();
const cacheClient = new DistributedCacheClient(config);
const app = express();

app.use(cacheClient.getSecurityMiddleware());

app.get('/api/data', async (req: Request, res: Response) => {
  await cacheClient.getCachedResponse(req, res, async () => {
    const data = { message: 'Cache miss - fresh data', timestamp: Date.now() };
    await cacheClient.set(cacheClient['computeCacheKey'](req), JSON.stringify({ status: 200, body: data }));
    res.json(data);
  });
});

app.get('/dashboard', (req: Request, res: Response) => {
  res.send('<html><body><h1>Cache Dashboard</h1></body></html>');
});

app.listen(3000, () => console.log('Cache service running on :3000'));

export { DistributedCacheClient, CacheConfig };
